/**
 * Reorders an array by moving an item from oldIndex to newIndex
 * @param array - The array to reorder
 * @param oldIndex - Current position of the item
 * @param newIndex - Target position for the item
 * @returns New array with item moved to target position
 */
export declare const reorderArray: <T>(array: T[], oldIndex: number, newIndex: number) => T[];
